source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');source(file.path(S,'nichenet_native_metrics.R'));suppressPackageStartupMessages(library(nichenetr));lt<-readRDS(file.path(REF,'ligand_target_matrix_nsga2r_final.rds'));d<-rd('de/M0046.tsv.gz');bg<-intersect(d$gene,rownames(lt));target<-intersect(d[FDR<.05,gene],bg);if(!length(target))target<-head(bg,1);set.seed(123);pot<-union(intersect(c('NECTIN2','PVR','VEGFA'),colnames(lt)),sample(colnames(lt),20));nt<-system.time(n<-as.data.table(predict_ligand_activities(target,bg,lt,pot)));ft<-system.time(f<-nichenet_four_metrics(target,bg,lt,pot));z<-merge(n,f,by='test_ligand',suffixes=c('_native','_fast'));out<-rbindlist(lapply(c('auroc','aupr','aupr_corrected','pearson'),function(v){a<-z[[paste0(v,'_native')]];b<-z[[paste0(v,'_fast')]];data.table(validation_case='sparse_target',n_targets=length(target),metric=v,n_ligands=nrow(z),max_absolute_error=max(abs(a-b),na.rm=TRUE),pass=identical(is.na(a),is.na(b))&&max(abs(a-b),na.rm=TRUE)<1e-12,native_seconds=nt['elapsed'],fast_seconds=ft['elapsed'])}));put(out,'nichenet_sparse_target_validation.tsv');print(out);stopifnot(all(out$pass))
